# =====================================================================
#  realestate.map - phishing phrases for real estate agencies,
#  property managers, developers, title / escrow and rental companies
#  Part of: phywall by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : closing / settlement wire fraud (changed escrow or title
#           bank details), contracts and deeds via fake DocuSign or
#           "secure document" links, fake buyer proof of funds,
#           rental deposit scams, tenant / landlord account and
#           portal lures, listing portal account suspension (Zillow,
#           Rightmove, Idealista, Sahibinden, Bina.az, Avito, Cian),
#           property tax and title notices
#
#  Avoided: normal client mails ("is the apartment still available",
#           "can we schedule a viewing", "photos of the flat"),
#           because agents receive them every day.
# =====================================================================

# ===== English =====
# Closing / wire fraud
/(wiring|wire|payment)\s+instructions\s+(for\s+(the\s+|your\s+)?(closing|settlement|escrow|purchase)\s+)?(have\s+|has\s+)?(changed|been\s+updated|been\s+revised)/i
/(new|updated|revised|changed)\s+(escrow|title|closing|settlement|trust)\s+(account|bank)\s+(details|information|instructions)/i
/(please\s+)?(wire|transfer|send)\s+(the\s+)?(earnest\s+money|down\s+payment|closing\s+funds|deposit|balance)\s+to\s+(the\s+)?(new|updated|following)\s+(account|bank)/i
/(do\s+not|don'?t)\s+(use|send\s+to)\s+the\s+(previous|old|original)\s+(account|wiring\s+instructions)[^.]{0,40}(escrow|closing|settlement|title)/i
/(closing|settlement)\s+(date|funds)[^.]{0,30}(urgent|today|immediately)[^.]{0,30}(wire|transfer)/i
# Documents / e-signature
/(purchase|sale|sales|lease|rental|tenancy)\s+(agreement|contract)\s+(is\s+)?(ready|waiting|pending)\s+(for\s+(your\s+)?(signature|review)|to\s+(be\s+)?signed)[^.]{0,30}(docusign|link|portal|here)/i
/(review|sign|view)\s+(the\s+)?(closing\s+(documents?|disclosure)|settlement\s+statement|title\s+(deed|documents?)|deed\s+of\s+(sale|trust))\s+(here|online|via|below|securely)/i
/(secure|encrypted)\s+(property|closing|escrow|real\s+estate)\s+(documents?|file|message)\s+(has\s+been\s+)?(shared|sent)\s+(with\s+you)?/i
/(offer|counter-?offer)\s+(letter\s+)?(on|for)\s+(the\s+|your\s+)?(property|listing|house|apartment)\s+(has\s+been\s+)?(sent|submitted|attached)[^.]{0,30}(view|download|docusign|link)/i
# Fake buyers / proof of funds
/(proof\s+of\s+funds|pof|bank\s+(comfort\s+)?letter)\s+(for\s+the\s+(purchase|property|offer)\s+)?(is\s+)?(attached|enclosed|available)[^.]{0,30}(view|download|link|here)/i
/(cash\s+buyer|overseas\s+(investor|buyer)|foreign\s+investor)[^.]{0,50}(interested\s+in\s+(all|several|multiple)\s+(your\s+)?(properties|listings|units))/i
# Rental / deposit scams
/(i\s+am|i'?m)\s+(currently\s+)?(abroad|overseas|out\s+of\s+the\s+country|on\s+a\s+mission)[^.]{0,50}(keys?|apartment|flat|house)[^.]{0,50}(deposit|first\s+month|airbnb|courier)/i
/(security\s+)?deposit\s+(refund|return)\s+(is\s+)?(ready|approved|pending)[^.]{0,30}(verify|confirm|claim)\s+(your\s+)?(bank|card|details)/i
/(rent|rental)\s+payment\s+(has\s+)?(failed|was\s+declined|is\s+overdue)[^.]{0,30}(update|verify)\s+(your\s+)?(payment|card|bank)\s+(details|method)/i
/(tenant|resident|owner|landlord)\s+portal\s+(account\s+)?(will\s+be\s+|has\s+been\s+)?(suspended|locked|deactivated|expired)/i
# Listing portals
/(zillow|realtor\.com|rightmove|zoopla|idealista|immobilienscout|seloger|sahibinden|emlakjet|hepsiemlak|bina\.az|yeniemlak|avito|cian|domofond|bayut|property\s*finder)\s+(agent\s+|agency\s+|premium\s+)?(account|profile|listings?|subscription)\s+(has\s+been\s+|will\s+be\s+|is\s+)?(suspended|deactivated|removed|expired|restricted|on\s+hold)/i
/(your\s+)?(property\s+)?listings?\s+(has\s+|have\s+|will\s+)?(been\s+)?(removed|deactivated|flagged|hidden)[^.]{0,30}(verify|confirm|log\s*in|reactivate)/i
# Tax / title
/(property|real\s+estate|land)\s+tax\s+(payment\s+)?(is\s+)?(overdue|unpaid|outstanding|refund)[^.]{0,30}(pay|view|claim|link|portal)/i
/(title|ownership|deed)\s+(registration|transfer)\s+(has\s+been\s+)?(rejected|suspended|on\s+hold|flagged)/i

# ===== Spanish =====
/(nuevos?|actualizad[oa]s?)\s+(datos\s+bancarios|instrucciones\s+de\s+(pago|transferencia))\s+(para\s+)?(la\s+)?(firma|escritura|compraventa|arras|se[ñn]al)/iu
/(contrato\s+de\s+(arras|compraventa|alquiler|arrendamiento))\s+(listo|pendiente)\s+(para|de)\s+firma[^.]{0,30}(enlace|docusign|aqu[íi])/iu
